{"command": "python3 -c "
# Read grid
with open('/workdir/data/input.txt', 'r') as f:
    content = f.read()

# Parse the grid
lines = content.strip().split('\n')
grid = []
for line in lines:
    row = []
    for char in line:
        if char == 'O':
            row.append('O')
        elif char == 'X':
            row.append('X')
        else:
            row.append(' ')
    grid.append(row)

print('Grid shape:', len(grid), 'x', len(grid[0]) if grid else 0)
print('Grid:')
for row in grid:
    print(repr(row))
""}
